import{z as F,x as n,o as l,c as i,q as t,j as r,D as e,d as a,s,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"成本：RL 相对 SFT","description":"","frontmatter":{"title":"成本：RL 相对 SFT","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-cost-vs-sft.md","filePath":"llm/rlsys-cost-vs-sft.md","lastUpdated":1791413859000}'),C={name:"llm/rlsys-cost-vs-sft.md"};function d(p,E,D,R,S,m){const B=n("Mermaid");return l(),i("div",null,[E[2]||(E[2]=t('<h1 id="成本-rl-相对-sft" tabindex="-1">成本：RL 相对 SFT <a class="header-anchor" href="#成本-rl-相对-sft" aria-label="Permalink to &quot;成本：RL 相对 SFT&quot;">​</a></h1><div class="epigraph"><p>SFT 按 token 买算力，RL 按解出的题买算力——两本账的单位不同，混着比只会得出想要的结论。</p><footer>—— 据 Yao 等 DeepSpeed-Chat 2023 与 HybridFlow 的成本结构整理</footer></div><p><a href="/llm/rlsys-eval-in-loop">上一课</a>给循环装上了守门的评测，本课算钱：把 RL 训练与 SFT 的成本放上同一张桌。样本效率的算法面在 <a href="/llm/sft-vs-rl-efficiency">SFT 对 RL 的数据效率</a>讲过，本课只算工程账：同样的卡、同样的时间，两种训练各自买到什么，RL 的钱花在哪几栏、哪几栏是浪费。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SFT 的成本结构简单：预收集的 token 流水线式过前向反向，MFU 高且平稳，每 token 价格基本恒定。RL 的成本结构复杂：生成（自回归、长尾、低 MFU）加打分（又一个推理负载）加引用前向加训练前向反向，四段之间有排队与等待；生成段的成本还随训练漂移——模型变强后响应变长，每一步更贵。缺口是把「RL 贵在哪、值不值」从印象变成账本：哪些段占大头、哪些开销可以压、什么条件下 RL 的账能算平。答不出这三问的团队，通常是在用 SFT 的直觉给 RL 排预算，然后被生成段的账单吓到。</p><p><span class="marginnote">直觉类比：SFT 像「按食材付钱的包餐」，菜单价固定、厨房不停火；RL 像「按钓上来的鱼付钱」，鱼竿（生成）大部分时间在等鱼咬钩，还要雇品鉴师（RM）验货——账要按「每条鱼」记，不能按「甩竿次数」记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账单位先对齐：SFT 记「每有效 token 成本」，RL 记「每解出题成本」——分母不是生成的 token 数，而是金标判定的成功数。成本分四栏记。生成栏：rollout 墙钟，通常占大头；优化靠引擎吞吐、组内共享前缀、长度预算与早停，响应长度是成本上升的先行指标（接<a href="/llm/length-budget-rl">长度预算与截断</a>）。打分栏：RM 或验证器池的吞吐与超时，接打分服务课的降级配置。训练栏：与 SFT 同构，但样本少、批次小，MFU 偏低。闲置栏：三段衔接的空转，共置与异步就是为了压它（<a href="/llm/rollout-resource-sharing">Rollout 与训练资源复用</a>）。再记隐性两栏：消融与失败的试错成本（RL 对超参与实现细节更敏感，同一结论要跑更多次），以及奖励工程的人力成本——SFT 的标注费在 RL 里换形成环境、RM 与监控的建设费，不是消失。</p><p><span class="marginnote">同一块 GPU 上，SFT 的 MFU 常数倍于 RL 的全程平均：RL 的墙钟大头是生成与等待，不是矩阵乘。框架论文报告的加速倍数（如 HybridFlow 的 1.53×–20.57×）都是对「闲置栏」的压缩——比较前先看对方的基线把闲置压到了什么程度。</span></p><p><span class="marginnote">数字实例：长度翻倍、成功率减半时，「解出题数」除以二、「生成 token」乘二，每解出题成本大约变成四倍——这就是边界里「翻两番」的来历，也是响应长度被叫作成本先行指标的原因。</span></p>',10)),(l(),r(o,null,{default:e(()=>[s(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SFT%5B%22SFT%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%B7%B2%E4%BB%98%EF%BC%8C%E7%AE%97%E5%8A%9B%E4%B9%B0%20token%22%5D%20--%3E%20A%5B%22%E5%89%8D%E5%90%91%20%2B%20%E5%8F%8D%E5%90%91%EF%BC%88MFU%20%E9%AB%98%EF%BC%89%22%5D%20--%3E%20U1%5B%22%E6%AF%8F%E6%9C%89%E6%95%88%20token%20%E6%88%90%E6%9C%AC%22%5D%0A%20%20RL%5B%22RL%EF%BC%9A%E7%AE%97%E5%8A%9B%E4%B9%B0%E7%BB%8F%E9%AA%8C%EF%BC%8C%E6%95%B0%E6%8D%AE%E8%87%AA%E4%BA%A7%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%88%E5%A4%A7%E5%A4%B4%EF%BC%8CMFU%20%E4%BD%8E%EF%BC%89%22%5D%0A%20%20RL%20--%3E%20RM%5B%22%E6%89%93%E5%88%86%EF%BC%9ARM%20%E6%88%96%E9%AA%8C%E8%AF%81%E5%99%A8%E6%B1%A0%22%5D%0A%20%20RL%20--%3E%20TR2%5B%22%E8%AE%AD%E7%BB%83%E5%89%8D%E5%90%91%E5%8F%8D%E5%90%91%20%2B%20%E5%BC%95%E7%94%A8%E5%89%8D%E5%90%91%22%5D%0A%20%20GEN%20--%3E%20IDLE%5B%22%E6%8E%92%E9%98%9F%E4%B8%8E%E7%AD%89%E5%BE%85%EF%BC%9A%E9%97%B2%E7%BD%AE%E6%A0%8F%22%5D%0A%20%20RM%20--%3E%20IDLE%0A%20%20IDLE%20--%3E%20U2%5B%22%E6%AF%8F%E8%A7%A3%E5%87%BA%E9%A2%98%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("RL 的账在什么条件下算平：当生成便宜（响应短、环境快、可验证）且成功信号可作分母时，RL 用算力置换标注——SFT 每条数据都付过人费，RL 的经验自产，边际数据成本接近零；当任务恰好「训练时可自测、部署时才见分晓」，RL 买到的能力增量很难用更多 SFT 数据买到（"),A("a",{href:"/llm/reasoning-rl-loop"},"推理 RL 闭环"),a("的闭环逻辑）。反过来，环境慢、轨迹长、奖励要人审时，三栏成本同时膨胀，账就难平。缩放视角下这笔账是动态的："),A("a",{href:"/llm/rl-scaling-laws"},"RL 缩放律"),a("回答「多买一倍算力买到多少」，本课回答「现在这倍算力怎么花得省」——两问合起来才是预算决策。")],-1)),(l(),r(o,null,{default:e(()=>[s(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22RL%20%E7%9A%84%E8%B4%A6%E8%83%BD%E4%B8%8D%E8%83%BD%E7%AE%97%E5%B9%B3%EF%BC%9F%22%5D%20--%3E%20G%7B%22%E7%94%9F%E6%88%90%E8%B4%B5%E4%B8%8D%E8%B4%B5%EF%BC%9F%22%7D%0A%20%20G%20--%3E%7C%22%E5%93%8D%E5%BA%94%E7%9F%AD%E3%80%81%E7%8E%AF%E5%A2%83%E5%BF%AB%E3%80%81%E5%8F%AF%E9%AA%8C%E8%AF%81%22%7C%20C1%5B%22%E7%94%9F%E6%88%90%E6%A0%8F%E5%B0%8F%22%5D%0A%20%20G%20--%3E%7C%22%E8%BD%A8%E8%BF%B9%E9%95%BF%E3%80%81%E7%8E%AF%E5%A2%83%E6%85%A2%22%7C%20C2%5B%22%E7%94%9F%E6%88%90%E6%A0%8F%E7%88%86%E7%82%B8%22%5D%0A%20%20Q%20--%3E%20S%7B%22%E6%88%90%E5%8A%9F%E5%8F%AF%E8%87%AA%E5%8A%A8%E5%88%A4%E5%AE%9A%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E9%87%91%E6%A0%87%E5%8F%AF%E8%87%AA%E6%B5%8B%22%7C%20C3%5B%22%E6%AF%8F%E8%A7%A3%E5%87%BA%E9%A2%98%E6%88%90%E6%9C%AC%E6%9C%89%E7%9C%9F%E5%88%86%E6%AF%8D%22%5D%0A%20%20S%20--%3E%7C%22%E8%A6%81%E4%BA%BA%E5%AE%A1%22%7C%20C4%5B%22%E9%9A%90%E6%80%A7%E4%BA%BA%E5%8A%9B%E6%A0%8F%E8%86%A8%E8%83%80%22%5D%0A%20%20C1%20--%3E%20OK%5B%22%E7%AE%97%E5%BE%97%E5%B9%B3%EF%BC%9A%E7%AE%97%E5%8A%9B%E6%8D%A2%E6%A0%87%E6%B3%A8%22%5D%0A%20%20C3%20--%3E%20OK%0A%20%20C2%20--%3E%20NO%5B%22%E8%B4%A6%E9%9A%BE%E5%B9%B3%EF%BC%9ASFT%20%E6%9B%B4%E5%B9%B2%E5%87%80%22%5D%0A%20%20C4%20--%3E%20NO%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">为什么重要：引用「RL 比 SFT 贵 \\(N\\) 倍」时不带长度与成功率条件，预算会错一个数量级。签预算前先在自己任务上量三个数：平均响应长度、金标成功率、生成墙钟占比——三个数齐了，账本才有可比性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本模型对序列长度与成功率都敏感：长度翻倍、成功率减半，每解出题成本约翻两番——引用任何「RL 比 SFT 贵几倍」的结论都要带上这两个条件。加速比对基线实现极其敏感，跨论文的倍数不可直接比。人力成本很少出现在框架论文的账里，却常常是预算的真实边界；把它显式记账，是 RL 预算评估与 SFT 预算评估最大的不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>记账单位对齐：SFT 记每有效 token，RL 记每解出题；分母用金标成功数，不是生成 token 量。</li><li>RL 四栏账：生成大头、打分、训练（MFU 偏低）、闲置；共置与异步压的是闲置栏。</li><li>隐性两栏：消融试错与奖励工程人力——标注成本换形，不消失。</li><li>RL 账算平的条件：生成便宜、环境快、成功可自测；否则 SFT 的账更干净。</li><li>出处：Yao 等，DeepSpeed-Chat，2023；Sheng 等，HybridFlow，EuroSys 2025；据各框架成本报告整理。</li></ul>',5))])}const h=F(C,[["render",d]]);export{L as __pageData,h as default};
